import json
lines = []
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/logs/workers/worker_code_direct-correction-ablation_20260517T021826.log') as f:
    for line in f:
        line = line.strip()
        if line:
            try:
                obj = json.loads(line)
                if obj.get('type') == 'result':
                    lines.append(str(obj.get('result', ''))[:2000])
                elif obj.get('type') == 'user':
                    msg = obj.get('message', {})
                    content = msg.get('content', [])
                    if isinstance(content, list):
                        for block in content:
                            if isinstance(block, dict) and block.get('type') == 'tool_result':
                                c = block.get('content', '')
                                if 'error' in c.lower() or 'fail' in c.lower() or 'submit_training' in c.lower():
                                    lines.append(c[:1000])
            except:
                pass
print('Last entries:')
for t in lines[-10:]:
    print('---')
    print(t[:500])
